<?php
require dirname(__DIR__).'/app/bootstrap.php';require_owner();require dirname(__DIR__).'/app/layout.php';require dirname(__DIR__).'/app/permissions.php';$error='';$edit=$_GET['edit']??'';$record=[];if($edit!==''&&$edit!=='new'){$record=one("SELECT * FROM users WHERE id=? AND business_id=? AND role='manager'",[(int)$edit,bid()])??[];if(!$record){http_response_code(404);exit('Manager not found.');}}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$id=(int)($_POST['id']??0);if(($_POST['action']??'')==='deactivate'){query("UPDATE users SET active=0 WHERE id=? AND business_id=? AND role='manager'",[$id,bid()]);audit('manager.deactivated','user',$id);flash('Manager deactivated. Access has been revoked.');redirect('managers.php');}$name=required_text('name',120);$email=strtolower(required_text('email',190));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new DomainException('Enter a valid email address.');$permissions=valid_permissions($_POST['permissions']??[]);$password=(string)($_POST['password']??'');if((!$id||$password!=='')&&strlen($password)<12)throw new DomainException('Use a password of at least 12 characters.');if(scalar('SELECT COUNT(*) FROM users WHERE email=? AND id<>?',[$email,$id]))throw new DomainException('This email is already in use.');transaction(function()use($id,$name,$email,$permissions,$password){if($id){$u=one("SELECT * FROM users WHERE id=? AND business_id=? AND role='manager' FOR UPDATE",[$id,bid()]);if(!$u)throw new DomainException('Manager not found.');query('UPDATE users SET name=?,email=?,permissions=?,active=? WHERE id=? AND business_id=?',[$name,$email,json_encode($permissions),isset($_POST['active'])?1:0,$id,bid()]);if($password!=='')query('UPDATE users SET password_hash=? WHERE id=? AND business_id=?',[password_hash($password,PASSWORD_DEFAULT),$id,bid()]);}else {query("INSERT INTO users(business_id,name,email,password_hash,role,permissions) VALUES(?,?,?,?,'manager',?)",[bid(),$name,$email,password_hash($password,PASSWORD_DEFAULT),json_encode($permissions)]);$id=(int)db()->lastInsertId();}audit('manager.permissions_updated','user',$id,['permissions'=>$permissions]);});flash('Manager and permissions saved.');redirect('managers.php');}catch(DomainException $ex){$error=$ex->getMessage();$record=array_merge($record,$_POST);}}
page_start('Managers','A trusted team. The right access for every person.','<a class="btn primary" href="managers.php?edit=new">'.icon('plus').' Add manager</a>');error_notice($error);
if($edit!==''):$selected=is_array($record['permissions']??null)?$record['permissions']:json_decode($record['permissions']??'[]',true);?><form method="post" class="panel form-panel"><h2><?= $edit==='new'?'Create manager account':'Manager permissions' ?></h2><p>Permissions are checked on the server for every operation. Owner access cannot be transferred here.</p><?php csrf_field(); ?><input type="hidden" name="id" value="<?= (int)($record['id']??0) ?>"><div class="form-grid"><?php field('name',['Full name','text',true],$record['name']??'');field('email',['Email address','email',true],$record['email']??'');field('password',[$edit==='new'?'Initial password (12+ characters)':'New password (leave blank to keep current)','password',$edit==='new']); ?><label class="field"><span>Account status</span><span><input type="checkbox" name="active" <?= ($record['active']??1)?'checked':'' ?>> Active account</span></label></div><?php foreach(permission_options() as $module=>$actions): ?><h3><?= e(ucfirst($module)) ?></h3><div class="permission-grid"><?php foreach($actions as $a):$key=$module.'.'.$a;?><label><input type="checkbox" name="permissions[]" value="<?= $key ?>" <?= in_array($key,$selected,true)?'checked':'' ?>><?= e(ucfirst($a)) ?></label><?php endforeach; ?></div><?php endforeach; ?><div class="form-actions"><a class="btn" href="managers.php">Cancel</a><button class="btn primary">Save permissions</button></div></form><?php else:$managers=rows("SELECT * FROM users WHERE business_id=? AND role='manager' ORDER BY name",[bid()]);?><section class="panel"><div class="table-scroll"><table><thead><tr><th>MANAGER</th><th>EMAIL</th><th>STATUS</th><th>LAST SIGN-IN</th><th>PERMISSIONS</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($managers as $m): ?><tr><td><div class="cell-person"><span class="avatar blue"><?= e(initials($m['name'])) ?></span><strong><?= e($m['name']) ?></strong></div></td><td><?= e($m['email']) ?></td><td><?= badge($m['active']?'Active':'Inactive') ?></td><td><?= date_label($m['last_login']) ?></td><td><?= count(json_decode($m['permissions'],true)) ?> permissions</td><td><div class="inline-actions"><a class="btn small" href="managers.php?edit=<?= $m['id'] ?>">Manage access</a><?php if($m['active']): ?><form method="post" data-confirm="Deactivate this Manager? Their access will be revoked immediately."><?php csrf_field(); ?><input type="hidden" name="id" value="<?= $m['id'] ?>"><input type="hidden" name="action" value="deactivate"><button class="btn small danger">Deactivate</button></form><?php endif; ?></div></td></tr><?php endforeach;if(!$managers): ?><tr><td colspan="6" class="empty">Your team starts here. Add your first Manager.</td></tr><?php endif; ?></tbody></table></div></section><?php endif;page_end(); ?>
